"use client";

import { AppShell } from "@/components/layout/AppShell";
import { CapabilityReviewSection } from "@/components/survey/CapabilityReviewSection";
import { ReviewSubmitSection } from "@/components/survey/ReviewSubmitSection";
import { SurveyCard } from "@/components/survey/SurveyCard";
import { SurveyFooterActions } from "@/components/survey/SurveyFooterActions";
import { SurveyHeader } from "@/components/survey/SurveyHeader";
import { SurveyStepper } from "@/components/survey/SurveyStepper";
import { needsCommentary } from "@/components/survey/surveyMath";
import { collectInitialWorkingState } from "@/components/survey/surveyState";
import { capabilityReviewData } from "@/data/capabilityReviewData";
import { surveyData } from "@/data/surveyData";
import type { SurveyNode, SurveyWorkingState } from "@/types/survey";
import { useRouter } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

type SurveyStep = 1 | 2 | 3;
type StoredSurveyFlowState = {
  capabilitySelections?: Record<string, boolean>;
  currentStep?: SurveyStep;
  workingState?: Partial<SurveyWorkingState>;
};

const flowStorageKey = "annual-labour-cost-survey-state";

function collectL3Nodes(nodes: SurveyNode[]) {
  const rows: SurveyNode[] = [];

  const visit = (node: SurveyNode) => {
    if (node.level === 3) {
      rows.push(node);
    }

    node.children?.forEach(visit);
  };

  nodes.forEach(visit);
  return rows;
}

function isSurveyStep(value: unknown): value is SurveyStep {
  return value === 1 || value === 2 || value === 3;
}

function hasNumericValue(value: string | undefined) {
  return Number.isFinite(Number.parseFloat(value ?? ""));
}

export default function Home() {
  const router = useRouter();
  const l3Rows = useMemo(() => collectL3Nodes(surveyData), []);
  const [currentStep, setCurrentStep] = useState<SurveyStep>(2);
  const [savedMessage, setSavedMessage] = useState("");
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});
  const [workingState, setWorkingState] = useState<SurveyWorkingState>(() =>
    collectInitialWorkingState(),
  );
  const [capabilitySelections, setCapabilitySelections] = useState<
    Record<string, boolean>
  >(() =>
    Object.fromEntries(
      capabilityReviewData.map((capability) => [capability.id, true]),
    ),
  );

  useEffect(() => {
    const restoreTimer = window.setTimeout(() => {
      const savedState = window.localStorage.getItem(flowStorageKey);

      if (!savedState) {
        return;
      }

      try {
        const parsed = JSON.parse(savedState) as StoredSurveyFlowState;

        if (parsed.capabilitySelections) {
          setCapabilitySelections((previous) => ({
            ...previous,
            ...parsed.capabilitySelections,
          }));
        }

        if (parsed.workingState) {
          const restoredWorkingState = parsed.workingState;

          setWorkingState((previous) => ({
            commentaryValues: {
              ...previous.commentaryValues,
              ...restoredWorkingState.commentaryValues,
            },
            currentValues: {
              ...previous.currentValues,
              ...restoredWorkingState.currentValues,
            },
            detailValues: {
              ...previous.detailValues,
              ...restoredWorkingState.detailValues,
            },
            expanded: {
              ...previous.expanded,
              ...restoredWorkingState.expanded,
            },
            priorValues: {
              ...previous.priorValues,
              ...restoredWorkingState.priorValues,
            },
          }));
        }

        if (isSurveyStep(parsed.currentStep)) {
          setCurrentStep(parsed.currentStep);
        }
      } catch {
        window.localStorage.removeItem(flowStorageKey);
      }
    }, 0);

    return () => window.clearTimeout(restoreTimer);
  }, []);

  const showSavedMessage = (message: string) => {
    setSavedMessage(message);
    window.setTimeout(() => setSavedMessage(""), 1800);
  };

  const persistFlowState = (step = currentStep) => {
    window.localStorage.setItem(
      flowStorageKey,
      JSON.stringify({
        capabilitySelections,
        currentStep: step,
        workingState,
      }),
    );
  };

  const saveFlowState = () => {
    persistFlowState();
    showSavedMessage("Saved");
  };

  const handleExit = () => {
    router.push("/labour-cost-insights");
  };

  const validateWorkingData = () => {
    const errors: Record<string, string> = {};

    l3Rows.forEach((row) => {
      const priorValue = workingState.priorValues[row.id];
      const currentValue = workingState.currentValues[row.id];

      if (!hasNumericValue(priorValue) || !hasNumericValue(currentValue)) {
        errors[row.id] = "Prior and Current values are required.";
        return;
      }

      if (
        needsCommentary(
          priorValue,
          currentValue,
        ) &&
        !workingState.commentaryValues[row.id]?.trim()
      ) {
        errors[row.id] = "Commentary is required for this variance.";
      }
    });

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleContinue = () => {
    if (currentStep === 1) {
      persistFlowState(2);
      setValidationErrors({});
      setCurrentStep(2);
      return;
    }

    if (currentStep === 2) {
      if (!validateWorkingData()) {
        return;
      }

      persistFlowState(3);
      setCurrentStep(3);
      return;
    }

    saveFlowState();
  };

  const handleBack = () => {
    setCurrentStep((step) => (step > 1 ? ((step - 1) as SurveyStep) : step));
  };

  const handleCapabilitySelectionChange = (id: string, isActive: boolean) => {
    setCapabilitySelections((previous) => ({
      ...previous,
      [id]: isActive,
    }));
  };

  const clearValidationError = (id: string) => {
    setValidationErrors((previous) => {
      if (!previous[id]) {
        return previous;
      }

      const next = { ...previous };
      delete next[id];
      return next;
    });
  };

  return (
    <AppShell>
      <main className="min-h-[calc(100vh-76px)] bg-[#F5F6F8] px-10 pb-0 pt-8 text-survey-text max-md:px-5">
        <div className="w-full">
          <SurveyHeader />
          <SurveyStepper currentStep={currentStep} />
          {currentStep === 1 ? (
            <CapabilityReviewSection
              capabilities={capabilityReviewData}
              selections={capabilitySelections}
              onSelectionChange={handleCapabilitySelectionChange}
            />
          ) : null}
          {currentStep === 2 ? (
            <SurveyCard
              onValidationErrorClear={clearValidationError}
              setWorkingState={setWorkingState}
              validationErrors={validationErrors}
              workingState={workingState}
            />
          ) : null}
          {currentStep === 3 ? <ReviewSubmitSection /> : null}
          <SurveyFooterActions
            savedMessage={savedMessage}
            showBack={currentStep > 1}
            onBack={handleBack}
            onContinue={handleContinue}
            onExit={handleExit}
            onSaveLater={saveFlowState}
          />
        </div>
      </main>
    </AppShell>
  );
}
